<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {api} from '../api';
import type {WorkflowLock} from '../workflowTypes';
import type {DeliveryModelLock} from '../deliveryTypes';
import type {ComponentInstance,SystemCatalogEntry,WorkflowMessageBinding} from '../systemTypes';
import {useActionFeedback} from '../composables/useNotifications';
const props=defineProps<{component:ComponentInstance;components:ComponentInstance[];catalog:SystemCatalogEntry[];providers:{id:string;kind:string;version:string}[]}>();
const emit=defineEmits<{owners:[NonNullable<ComponentInstance['workflowOwners']>];routes:[NonNullable<ComponentInstance['workflowMessages']>];bindings:[ComponentInstance['bindings']]}>();
const definition=(c:ComponentInstance)=>props.catalog.find(d=>d.kind==='definition'&&d.id===c.definition.id&&d.version===c.definition.version);
const aspects=computed(()=>definition(props.component)?.aspects?.filter(a=>a.kind==='workflow')||[]);
const rows=ref<{slot:string;lock:WorkflowLock}[]>([]),channels=ref<{componentId:string;slot:string;name:string;lock:DeliveryModelLock}[]>([]),busy=ref(''),error=ref(''),notice=ref('');useActionFeedback('Workflow bindings',busy,notice,error);
const stamp=computed(()=>JSON.stringify([props.component.definition,props.components.map(c=>[c.id,c.definition]),props.catalog]));watch(stamp,()=>{rows.value=[];channels.value=[];error.value='';});
async function load(){if(busy.value)return;const snapshot=stamp.value;busy.value='Loading pinned workflow and message contracts';error.value='';try{
 const [flows,messages]=await Promise.all([Promise.all(aspects.value.map(async a=>{const r=await api<{body:{workflow:WorkflowLock}}>('/systems/definitions/aspect','POST',a);return {slot:a.slot,lock:r.body.workflow};})),Promise.all(props.components.flatMap(c=>(definition(c)?.aspects||[]).filter(a=>a.kind==='messages').map(async a=>{const r=await api<{body:{model:DeliveryModelLock}}>('/systems/definitions/aspect','POST',a);return {componentId:c.id,slot:a.slot,name:c.name+' / '+a.slot,lock:r.body.model};})))]);
 if(snapshot===stamp.value){rows.value=flows;channels.value=messages;notice.value='Bind owners and every adapter task, then prepare execution to check capabilities and exact types.';}
 }catch(e){if(snapshot===stamp.value)error.value=(e as Error).message;}finally{busy.value='';}}
function owners(machine:{machineId:string;version:string;digest:string}){return props.components.flatMap(c=>(definition(c)?.aspects||[]).filter(a=>a.kind==='state'&&a.id===machine.machineId&&a.version===machine.version&&a.digest===machine.digest).map(a=>({value:JSON.stringify([c.id,a.slot]),name:c.name+' / '+a.slot})));}
function ownerValue(slot:string,ownerId:string){const o=props.component.workflowOwners?.find(o=>o.slot===slot&&o.ownerId===ownerId);return o?JSON.stringify([o.componentId,o.stateSlot]):'';}
function chooseOwner(slot:string,ownerId:string,value:string){const result=(props.component.workflowOwners||[]).filter(o=>o.slot!==slot||o.ownerId!==ownerId);if(value){const [componentId,stateSlot]=JSON.parse(value);result.push({slot,ownerId,componentId,stateSlot});}emit('owners',result);}
function bind(slot:string,id:string){const requirement='workflow/'+slot;const result=props.component.bindings.filter(b=>b.requirement!==requirement);if(id)result.push({requirement,resourceId:id});emit('bindings',result);}
function route(slot:string,nodeId:string):WorkflowMessageBinding{return props.component.workflowMessages?.find(r=>r.slot===slot&&r.nodeId===nodeId)||{slot,nodeId,channelComponentId:'',channelSlot:'',routeId:'',sourceNodeId:'',response:{}};}
function update(slot:string,nodeId:string,patch:Partial<WorkflowMessageBinding>){emit('routes',[...(props.component.workflowMessages||[]).filter(r=>r.slot!==slot||r.nodeId!==nodeId),{...route(slot,nodeId),...patch}]);}
function channel(slot:string,nodeId:string){const r=route(slot,nodeId);return channels.value.find(c=>c.componentId===r.channelComponentId&&c.slot===r.channelSlot);}
function chooseChannel(slot:string,nodeId:string,value:string){const [componentId,channelSlot]=value?JSON.parse(value):['',''];update(slot,nodeId,{channelComponentId:componentId,channelSlot,routeId:'',response:{}});}
function outputs(slot:string,nodeId:string){const c=channel(slot,nodeId),r=c?.lock.model.routes.find(r=>r.id===route(slot,nodeId).routeId),actor=c?.lock.model.instances.find(a=>a.id===r?.targetInstanceId);return c?.lock.model.machines.find(m=>m.digest===actor?.machine.digest)?.machine.commands.find(c=>c.name===r?.command)?.outputs||[];}
</script>
<template><section v-if="aspects.length" class="workflow-bindings"><h3>Workflow orchestration</h3><p>Commands use existing state owners. Broker handoffs resume only on a matching task acknowledgement. Human responses and signals remain explicit scenario events.</p><button :disabled="!!busy" @click="load">Load workflow bindings</button><p role="status">{{busy}}</p><p v-if="error" role="alert">{{error}}</p>
 <fieldset v-for="row in rows" :key="row.slot"><legend>{{row.slot}} · {{row.lock.workflow.name}}</legend><label>Workflow provider *<select :value="component.bindings.find(b=>b.requirement==='workflow/'+row.slot)?.resourceId||''" @change="bind(row.slot,($event.target as HTMLSelectElement).value)"><option value="">Choose…</option><option v-for="p in providers.filter(p=>p.kind==='modeled-workflow'&&p.version==='1.0.0')" :key="p.id" :value="p.id">{{p.id}}</option></select></label>
 <label v-for="owner in row.lock.workflow.owners" :key="owner.id">Shared owner: {{owner.name}} *<select :value="ownerValue(row.slot,owner.id)" @change="chooseOwner(row.slot,owner.id,($event.target as HTMLSelectElement).value)"><option value="">Choose exact matching state owner…</option><option v-for="choice in owners(owner.machine)" :key="choice.value" :value="choice.value">{{choice.name}}</option></select><small v-if="!owners(owner.machine).length">No exact machine version and digest is available in this design.</small></label>
 <fieldset v-for="node in row.lock.workflow.nodes.filter(n=>n.task?.kind==='adapter')" :key="node.id"><legend>{{node.name}} · required broker handoff</legend><label>Message channel *<select :value="route(row.slot,node.id).channelComponentId?JSON.stringify([route(row.slot,node.id).channelComponentId,route(row.slot,node.id).channelSlot]):''" @change="chooseChannel(row.slot,node.id,($event.target as HTMLSelectElement).value)"><option value="">Choose…</option><option v-for="c in channels" :key="c.componentId+c.slot" :value="JSON.stringify([c.componentId,c.slot])">{{c.name}}</option></select></label>
 <label>Route *<select :value="route(row.slot,node.id).routeId" @change="update(row.slot,node.id,{routeId:($event.target as HTMLSelectElement).value,response:{}})"><option value="">Choose…</option><option v-for="r in channel(row.slot,node.id)?.lock.model.routes||[]" :key="r.id" :value="r.id">{{r.name}}</option></select></label>
 <label>Source command node *<select :value="route(row.slot,node.id).sourceNodeId" @change="update(row.slot,node.id,{sourceNodeId:($event.target as HTMLSelectElement).value})"><option value="">Choose…</option><option v-for="n in row.lock.workflow.nodes.filter(n=>n.command)" :key="n.id" :value="n.id">{{n.name}} · {{n.command?.command}}</option></select></label>
 <label v-for="field in node.task?.response||[]" :key="field.name">Acknowledgement → {{field.name}} ({{field.type}}) *<select :value="route(row.slot,node.id).response[field.name]||''" @change="update(row.slot,node.id,{response:{...route(row.slot,node.id).response,[field.name]:($event.target as HTMLSelectElement).value}})"><option value="">Choose a recipient output…</option><option v-for="p in outputs(row.slot,node.id).filter(p=>p.type===field.type&&JSON.stringify(p.recordRef)===JSON.stringify(field.recordRef))" :key="p.name" :value="p.name">{{p.name}}</option></select></label>
 <button @click="emit('routes',(component.workflowMessages||[]).filter(r=>r.slot!==row.slot||r.nodeId!==node.id))">Clear handoff binding</button></fieldset></fieldset>
 <p v-for="(o,i) in component.workflowOwners||[]" :key="i">{{o.slot}} / {{o.ownerId}} → {{o.componentId}} / {{o.stateSlot}} <button @click="emit('owners',(component.workflowOwners||[]).filter((_,j)=>i!==j))">Remove</button></p>
</section></template>
<style scoped>.workflow-bindings,fieldset{min-width:0}fieldset{margin:12px 0;padding:10px;border:1px solid #cbdce3}label{display:grid;gap:6px;margin:10px 0}select{min-width:0;width:100%;padding:8px}p,small{font-size:12px;line-height:1.5;overflow-wrap:anywhere}</style>
